def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def safe_pos(v, default=(0, 0)):
        try:
            if isinstance(v, (list, tuple)) and len(v) >= 2:
                return int(v[0]), int(v[1])
        except Exception:
            pass
        return default

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(src, dst):
        return [clamp_step(dst[0] - src[0]), clamp_step(dst[1] - src[1])]

    def step_away(src, dst):
        return [clamp_step(src[0] - dst[0]), clamp_step(src[1] - dst[1])]

    def best_by_distance(points, origin, prefer_far=False):
        best = None
        best_score = None
        for p in points or []:
            pp = safe_pos(p, None)
            if pp is None:
                continue
            d = manhattan(pp, origin)
            score = (-d if prefer_far else d, pp[0], pp[1])
            if best is None or score < best_score:
                best = pp
                best_score = score
        return best

    env = observation.get("environment_name", "resource_collection")
    sx, sy = safe_pos(observation.get("self_position"), (0, 0))
    ox, oy = safe_pos(observation.get("opponent_position"), (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    w = observation.get("grid_width", 0)
    h = observation.get("grid_height", 0)
    try:
        w = int(w)
    except Exception:
        w = 0
    try:
        h = int(h)
    except Exception:
        h = 0

    center = (w // 2, h // 2) if w > 0 and h > 0 else self_pos

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)

        corners = []
        if w > 0 and h > 0:
            corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        else:
            corners = [(0, 0), (-1, 0), (0, -1), (-1, -1)]
        target = best_by_distance(corners, opp_pos, prefer_far=True)
        if target is None:
            return step_away(self_pos, opp_pos)
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or []
        target = best_by_distance(targets, self_pos, prefer_far=False)
        if target is not None:
            return step_toward(self_pos, target)

        # No obvious target: move toward center or pressure opponent territory.
        if w > 0 and h > 0 and (self_pos != center):
            return step_toward(self_pos, center)
        return step_toward(self_pos, opp_pos)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    target = best_by_distance(resources, self_pos, prefer_far=False)
    if target is not None:
        # If opponent is clearly closer, bias to a different axis by moving toward resource anyway.
        return step_toward(self_pos, target)

    # Fallbacks when no resources are visible.
    if env == "resource_collection":
        if self_pos != center:
            return step_toward(self_pos, center)
        return step_toward(self_pos, opp_pos)

    # Generic safe fallback.
    return step_toward(self_pos, center)

